792	/* 每 tick 调一次：发一片。发完就收工。 */
793	static void mqtt_hist_pump(void)
794	{
795	    char   raw[MQTT_HIST_RAW + 4];
796	    char   b64[(MQTT_HIST_RAW * 4) / 3 + 8];
797	    size_t n, b64len = 0;
798	    size_t off;
799	    int    seq, total;
800	    char   to[sizeof(s_hist_to)];
801	    char   target[sizeof(s_hist_target)];
802	
803	    pthread_mutex_lock(&s_hist_lock);
804	
805	    if (s_hist_buf == NULL) {
806	        pthread_mutex_unlock(&s_hist_lock);
807	        return;
808	    }
809	
810	    /* 发完了（或者片数到了上限）：释放，收工 */
811	    if (s_hist_off >= s_hist_len || s_hist_seq >= s_hist_total) {
812	        syslog(LOG_INFO, "[%s] history: 发送完成，共 %d 片\n", TAG, s_hist_seq);
813	        free(s_hist_buf);
814	        s_hist_buf = NULL;
815	        pthread_mutex_unlock(&s_hist_lock);
816	        return;
817	    }
818	
819	    n = MQTT_HIST_RAW;
820	    if (s_hist_off + n > s_hist_len) {
821	        n = s_hist_len - s_hist_off;
822	    }
823	
824	    /* 不要切在多字节字符中间：回退到最后一个 UTF-8 起始字节。
825	     * 只在后面还有数据时才需要退 —— 正好切在末尾是合法的。 */
826	    while (n > 1 && (s_hist_off + n) < s_hist_len
827	           && ((unsigned char)s_hist_buf[s_hist_off + n] & 0xC0) == 0x80) {
828	        n--;
829	    }
830	
831	    if (n == 0) {
832	        free(s_hist_buf);
833	        s_hist_buf = NULL;
834	        pthread_mutex_unlock(&s_hist_lock);
835	        return;
836	    }
837	
838	    off   = s_hist_off;
839	    seq   = s_hist_seq;
840	    total = s_hist_total;
841	    memcpy(to, s_hist_to, sizeof(to));
842	    memcpy(target, s_hist_target, sizeof(target));
843	
844	    memcpy(raw, s_hist_buf + off, n);
845	    s_hist_off += n;
846	    s_hist_seq++;
847	
848	    pthread_mutex_unlock(&s_hist_lock);
849	
850	    if (mbedtls_base64_encode((unsigned char *)b64, sizeof(b64), &b64len,
851	                              (const unsigned char *)raw, n) != 0) {
852	        syslog(LOG_ERR, "[%s] history: base64 失败，丢掉这一片\n", TAG);
853	        return;
854	    }
855	
856	    b64[b64len] = '\0';
857	
858	    mqtt_hist_publish(to, target, seq, total, b64);
859	}

