887	        syslog(LOG_ERR, "[%s] history: 内存不足\n", TAG);
888	        return;
889	    }
890	
891	    /* 没有会话文件时它会写 "[]" 并返回 OK —— 正好，空档案也是一种结果，
892	     * 照样发回去，让家长端显示「还没有记录」，不用另开一条消息类型。 */
893	    if (session_get_history_json(target, buf, MQTT_HIST_MAX, 200) != OK) {
894	        free(buf);
