896	        return;
897	    }
898	
899	    len = strlen(buf);
900	
901	    pthread_mutex_lock(&s_hist_lock);
902	
903	    s_hist_buf   = buf;
904	    s_hist_len   = len;
905	    s_hist_off   = 0;
906	    s_hist_seq   = 0;
907	    s_hist_total = (int)((len + MQTT_HIST_RAW - 1) / MQTT_HIST_RAW);
908	
909	    if (s_hist_total <= 0) {
910	        s_hist_total = 1;
911	    }
912	    if (s_hist_total > MQTT_HIST_MAXSEQ) {
913	        s_hist_total = MQTT_HIST_MAXSEQ;
914	    }
915	
916	    strncpy(s_hist_to, to, sizeof(s_hist_to) - 1);
917	    s_hist_to[sizeof(s_hist_to) - 1] = '\0';
918	    strncpy(s_hist_target, target, sizeof(s_hist_target) - 1);
919	    s_hist_target[sizeof(s_hist_target) - 1] = '\0';
920	
921	    pthread_mutex_unlock(&s_hist_lock);
922	
923	    syslog(LOG_INFO, "[%s] history: %s -> %s, %u 字节, %d 片，开始发送\n",
924	           TAG, target, to, (unsigned)len, s_hist_total);
925	}
