/* ── 给孩子以外的人发一条消息（分享通知 / 情绪转介共用） ──────────
 *
 * 目的地优先用家长留的上报地址（g_report_channel / g_report_chat_id），
 * 没有就落到 MQTT 默认的 parent。velaclaw_publish 是异步的，从 LVGL
 * 线程调用不会卡界面。 */
static void publish_to_parent(const char *text)
{
    char channel[sizeof(g_report_channel)];
    char chat_id[sizeof(g_report_chat_id)];

    if (text == NULL || text[0] == '\0')
      {
        return;
      }

    pthread_mutex_lock(&g_msg_lock);
    memcpy(channel, g_report_channel, sizeof(channel));
    memcpy(chat_id, g_report_chat_id, sizeof(chat_id));
    pthread_mutex_unlock(&g_msg_lock);

    if (channel[0] == '\0')
      {
        strncpy(channel, "mqtt", sizeof(channel) - 1);
        channel[sizeof(channel) - 1] = '\0';
      }

    if (chat_id[0] == '\0')
      {
        strncpy(chat_id, "parent", sizeof(chat_id) - 1);
        chat_id[sizeof(chat_id) - 1] = '\0';
      }

    if (g_agent_client != NULL)
      {
        velaclaw_publish(g_agent_client, channel, chat_id, text);
      }
}

/* ── 孩子主动分享：把这次冒险切进分享档案 ────────────────────────
 *
 * 板子上有两份会话：
 *   1. 故事会话（story_chat_id）—— 孩子自己的完整剧情，用来续讲；
 *   2. 分享档案（kid_buddy:share）—— 只放孩子明确同意分享的段落。
 *
 * 家长端只同步第 2 份，所以「家长看到的是孩子主动分享的作品」这句话
 * 在实现上成立，而不是靠网页自觉。切片的依据是会话文件里每条消息的 ts：
 * 从 g_story_started_at 到现在，且没被上一次分享覆盖过。
 *
 * 文件路径规则必须和 ai_agent 的 session_mgr 一致：
 *   <AGENT_SESSION_DIR>/tg_<sanitize(chat_id)>.jsonl
 * sanitize 只保留字母数字和 - _ .，其余字符换成下划线。 */
#define STORY_SHARE_CHAT_ID "kid_buddy:share"
#define SHARE_LINE_MAX      2048

static void session_file_for(const char *chat_id, char *buf, size_t size)
{
    char safe[64];
    size_t i;

    for (i = 0; i + 1 < sizeof(safe) && chat_id[i] != '\0'; i++)
      {
        unsigned char c = (unsigned char)chat_id[i];

        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
            || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.')
          {
            safe[i] = (char)c;
          }
        else
          {
            safe[i] = '_';
          }
      }

    safe[i] = '\0';
    snprintf(buf, size, "%s/tg_%s.jsonl", AGENT_SESSION_DIR, safe);
}

static int share_copy_adventure(void)
{
    char src[160];
    char dst[160];
    char line[SHARE_LINE_MAX];
    int64_t start   = g_story_started_at;
    int64_t through = g_story_shared_through;
    int copied = 0;
    FILE *in, *out;

    session_file_for(story_chat_id(), src, sizeof(src));
    session_file_for(STORY_SHARE_CHAT_ID, dst, sizeof(dst));

    in = fopen(src, "r");
    if (in == NULL)
      {
        return 0;
      }

    out = fopen(dst, "a");
    if (out == NULL)
      {
        fclose(in);
        syslog(LOG_ERR, "[kid_buddy] share: 打不开分享档案 %s\n", dst);
        return 0;
      }

    /* 开机时时钟没校上（停在 1970）就先回看一小时，总比把整个会话
     * 都当成这次冒险要好。正常路径下 start 一定是真的。 */
    if (start <= 0)
      {
        start = (int64_t)time(NULL) - 3600;
      }

    while (fgets(line, sizeof(line), in) != NULL)
      {
        const char *p = strstr(line, "\"ts\":");
        size_t len = strlen(line);
        double ts;

        /* 只接受完整的一行。另一个线程正在写最后一条时，这里可能读到
         * 半行，抄进分享档案会让手机端整个 JSON 解析失败。 */
        if (p == NULL || len == 0 || line[len - 1] != '\n'
            || strstr(line, "\"role\":") == NULL)
          {
            continue;
          }

        ts = strtod(p + 5, NULL);

        if (ts < (double)start || ts <= (double)through)
          {
            continue;
          }

        fputs(line, out);
        copied++;

        if ((int64_t)ts > through)
          {
            through = (int64_t)ts;
          }
      }

    fclose(in);
    fclose(out);

    if (copied > 0)
      {
        g_story_shared_through = through;
      }

    return copied;
}

static void story_share_now(void)
{
    int copied = share_copy_adventure();
    char note[192];

    /* 这一轮的回答里要跟孩子确认一句，不能悄悄做了不说 */
    g_share_hint =
        "[孩子刚刚同意把这次冒险放进故事书]\n"
        "先用一句话告诉他：这次冒险已经放进故事书了，爸爸妈妈打开家长端就能看到。"
        "语气高兴一点，然后问他还想不想接着玩。\n";

    snprintf(note, sizeof(note),
             "【故事分享】孩子把刚才的冒险放进了故事书（%d 条记录）。"
