 * 同时给家长推一条提醒。
 *
 * 只认明确的说法，不猜语气。判断在词表，执行在板子 —— 和内容过滤同一套
 * 思路，误判的代价只是多一条家长提醒，不是把孩子的话藏起来。 */
static const char *const g_emotion_hard_words[] = {
    "不想活", "想死", "活着没意思", "自杀", "离家出走",
    "被欺负", "欺负我", "挨打", "没人喜欢我", "没人跟我玩",
    "没有人跟我玩", "讨厌自己", "我是多余的",
};

static const char *const g_emotion_soft_words[] = {
    "难过", "害怕", "想哭", "孤单", "没人理我", "不想上学",
    "不想去学校", "心情不好", "烦死了", "委屈",
};

#define EMOTION_HARD_COUNT \
    (sizeof(g_emotion_hard_words) / sizeof(g_emotion_hard_words[0]))
#define EMOTION_SOFT_COUNT \
    (sizeof(g_emotion_soft_words) / sizeof(g_emotion_soft_words[0]))

#define EMOTION_HINT_HARD \
    "[孩子刚才说了一件需要大人知道的事]\n" \
    "先温柔地接住他的情绪，用一两句话，不要追问细节，不要讲道理，也不要评判。" \
    "然后清楚地告诉他：这件事你会告诉爸爸妈妈，让大人来帮他。" \
    "不要说「我替你保密」，也不要答应不告诉别人。\n"

#define EMOTION_HINT_SOFT \
    "[孩子刚才的语气有点低落]\n" \
    "先接住他的情绪，再给一个轻松的小建议。不要追问，也不要说教。\n"

#define EMOTION_HARD_ALERT_GAP_MS  (10 * 60 * 1000)
#define EMOTION_SOFT_ALERT_GAP_MS  (60 * 60 * 1000)

static int64_t g_emotion_hard_alert_ms = 0;
static int64_t g_emotion_soft_alert_ms = 0;

static void emotion_note_utterance(const char *text)
{
    const char *hit = NULL;
    bool hard = false;
    char note[224];
    int64_t now = now_ms();
    int64_t *last;

    /* 剧情里说「我好害怕」多半是在演，别当成真事推给家长 */
    if (g_story_mode || text == NULL || text[0] == '\0')
      {
        return;
      }

    for (size_t i = 0; i < EMOTION_HARD_COUNT; i++)
      {
        if (strstr(text, g_emotion_hard_words[i]) != NULL)
          {
            hit  = g_emotion_hard_words[i];
            hard = true;
            break;
          }
      }

    if (hit == NULL)
      {
        for (size_t i = 0; i < EMOTION_SOFT_COUNT; i++)
          {
            if (strstr(text, g_emotion_soft_words[i]) != NULL)
              {
                hit = g_emotion_soft_words[i];
                break;
              }
          }
      }

    if (hit == NULL)
      {
        return;
      }

    g_emotion_hint = hard ? EMOTION_HINT_HARD : EMOTION_HINT_SOFT;

    last = hard ? &g_emotion_hard_alert_ms : &g_emotion_soft_alert_ms;

    if (now - *last < (hard ? EMOTION_HARD_ALERT_GAP_MS
                            : EMOTION_SOFT_ALERT_GAP_MS))
      {
        syslog(LOG_INFO, "[kid_buddy] emotion: 告警限流中（%s）\n", hit);
        return;
      }

    if (hard)
      {
        snprintf(note, sizeof(note),
                 "【重要提醒】孩子刚才提到了「%s」。设备已经安抚他，"
                 "并告诉他会把这件事告诉爸爸妈妈。请尽快找时间和他聊聊。",
                 hit);
      }
    else
      {
        snprintf(note, sizeof(note),
                 "【心情提醒】孩子刚才的话里听出一点低落（「%s」）。"
                 "设备已经安慰过他，你有空可以问问他今天怎么样。",
                 hit);
      }

    publish_to_parent(note);
    *last = now;

    syslog(LOG_INFO, "[kid_buddy] emotion: 命中「%s」（%s），已转介家长\n",
           hit, hard ? "重要" : "一般");
}

