function pad2(n){ return (n < 10 ? '0' : '') + n; }

function dayKey(ts){
  var d = new Date(ts * 1000);
  return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate());
}

function renderDaily(){
  dbOpen(function(d){
    if (!d) return;
    var rows = [];
    try {
      var tx = d.transaction(STORY_STORE, 'readonly');
      tx.objectStore(STORY_STORE).openCursor().onsuccess = function(e){
        var c = e.target.result;
        if (c) { rows.push(c.value); c.continue(); return; }
        dbRecent(4000, function(msgs){ drawDaily(rows, msgs); });
      };
    } catch(e){ drawDaily([], []); }
  });
}

function drawDaily(rows, msgs){
