/* 现在是不是睡觉时间？ */
static bool bedtime_now(void)
{
    time_t    now;
    struct tm tm;

    if (g_sleep_from == g_sleep_to)
      {
        return false;              /* 起止相同 = 这个功能关着 */
      }

    /* 时钟不可信就不判 —— 宁可它醒着，也不能让它在错误的钟点上睡觉 */
    if (!agent_clock_is_verified())
      {
        return false;
      }

    now = time(NULL);

    if (localtime_r(&now, &tm) == NULL)
      {
        return false;
      }

    if (g_sleep_from < g_sleep_to)
      {
        /* 同一天之内，比如 13 → 15 */
        return tm.tm_hour >= g_sleep_from && tm.tm_hour < g_sleep_to;
      }

    /* 跨午夜，比如 21 → 7 */
    return tm.tm_hour >= g_sleep_from || tm.tm_hour < g_sleep_to;
}

/* 脸谱每秒要问十次「现在是不是睡觉时间」，每次真去 time() + localtime_r
 * 没必要 —— 按分钟缓存一下，跨分钟才重算。 */
static bool bedtime_cached(void)
{
    static int  cached_minute = -1;
    static bool cached_value  = false;
    int         minute        = (int)(time(NULL) / 60);

    if (minute != cached_minute)
      {
        cached_minute = minute;
        cached_value  = bedtime_now();
      }

    return cached_value;
}

