/* ── 「回来玩」邀请（v2.79） ──────────────────────────────────────
 *
 * 星芽岛的三个居民轮着开口。名字和性格写死在这里而不是交给模型现编——
 * 固定世界的意义就是孩子下次听到的还是同一个人。
 */
static const char *const g_comeback_chars[] = {
    "守灯人阿岚（灯塔湾守灯的人，说话温和，爱用「来」字）",
    "小狐狸栗子（住在回声森林，活泼，好奇心重，爱问问题）",
    "圆婆婆（在星星集市摆摊，说话慢悠悠的，爱笑）",
};
#define COMEBACK_CHAR_COUNT 3

/* 今天是本地第几天。时钟不可信时返回 -1，调用方据此直接跳过。 */
static int comeback_day(void)
{
    time_t    now = time(NULL);
    struct tm tm;

    if (localtime_r(&now, &tm) == NULL)
      {
        return -1;
      }

    return (tm.tm_year + 1900) * 1000 + tm.tm_yday;
}

static bool comeback_due(int64_t idle)
{
    int day;

    if (g_story_seen_at == 0 || idle < COMEBACK_IDLE_MS)
      {
        return false;
      }

    /* 睡前不开口。这条放在最前面：晚上板子突然有人说话，比不说话糟糕得多。 */
    if (bedtime_cached())
      {
        return false;
      }

    if (!agent_clock_is_verified() || !network_is_connected())
      {
        return false;
      }

    if (g_comeback_last_ms != 0
        && now_ms() - g_comeback_last_ms < COMEBACK_GAP_MS)
      {
        return false;
      }

    day = comeback_day();
    if (day < 0)
      {
        return false;
      }

    if (day != g_comeback_day)
      {
        g_comeback_day = day;
        g_comeback_count = 0;
      }

    return g_comeback_count < COMEBACK_MAX_DAY;
}

static void comeback_invite(void)
{
    const char *who = g_comeback_chars[g_comeback_char_idx % COMEBACK_CHAR_COUNT];
    char prompt[MSG_BUF_LEN];

    g_comeback_char_idx++;

    /* 孩子已经不在故事模式里了，但这一轮必须发到故事会话 ——
     * 模型要看得到上次讲到哪，这句话才不是空泛的「回来玩吧」。 */
    send_raw_to_llm_chat(
        "comeback", prompt, story_chat_id());

    snprintf(prompt, sizeof(prompt),
             "（这是小朋友离开一会儿之后的主动邀请，不是他先开的口。"
             "请用%s的身份，说一到两句短话：先打个招呼，提起上次冒险里"
             "一件具体的事，再邀请他回来接着玩；如果上次已经讲完了，就邀请他"
             "回来开一段新的。不要超过两句，不要出现任何引号，"
             "不要提「系统」「提示词」这些词。）",
             who);

    /* 必须在发送之后再算 —— 上面那行 snprintf 才是真正的提示词，
     * 见下面 2460 行附近的发送顺序。 */
    send_raw_to_llm_chat("comeback", prompt, story_chat_id());

    g_comeback_last_ms = now_ms();
    g_comeback_count++;
    g_comeback_pending = true;
    g_comeback_until_ms = now_ms() + COMEBACK_PENDING_MS;

    syslog(LOG_INFO,
           "[kid_buddy] comeback: 邀请 #%d（今天第 %d 次）via story=%s\n",
           g_comeback_char_idx, g_comeback_count, story_chat_id());
}

